SELECT 'artist_biography', 'en', 1, '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Tunes — Víctor Cabrera, born on 12 April 1981 — is a Dominican record producer, and one half of ","type":"text"},{"type":"artistReference","attrs":{"artistId":"ef56311a-ac4b-451e-a7a7-97e5f240cd47","displayText":"Luny Tunes","occurrenceId":"39137a43-a864-4c68-bb9a-3920ef0ca398"}},{"text":". With ","type":"text"},{"type":"artistReference","attrs":{"artistId":"e611e3fc-c00d-46e6-b397-27425787d6d1","displayText":"Luny","occurrenceId":"3399ba14-1f00-41c9-8a06-17f22e602a7d"}},{"text":" he built a large part of what commercial reggaetón sounds like.","type":"text"}]},{"type":"paragraph","content":[{"text":"The Harvard kitchen","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Before any of it, he and Francisco Saldaña were working at Harvard University — one as a chef, the other washing dishes. Two Dominican immigrants in a Massachusetts kitchen is where the most successful production duo in the history of the genre started.","type":"text"}]},{"type":"paragraph","content":[{"text":"The detail gets told often, and what it carries is this: neither man came out of an industry or a conservatory. They learned production on their own equipment, in their own time, after shifts.","type":"text"}]},{"type":"paragraph","content":[{"text":"The break","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"DJ Nelson gave them their opening, and the records came out through Flow Music, his label. From there Luny Tunes became the production signature of reggaetón’s breakthrough years, and the beats they made were the ones everyone else was measured against.","type":"text"}]},{"type":"paragraph","content":[{"text":"Their Mas Flow imprint became a label in its own right, and other Dominican producers worked in its orbit — ","type":"text"},{"type":"artistReference","attrs":{"artistId":"f6865535-50d6-46a2-991e-402a5f3b27d6","displayText":"DJ Urba","occurrenceId":"014792f0-36d1-432d-80b5-c7ff7df3ade4"}},{"text":" among them, on the Daddy Yankee records of the same decade.","type":"text"}]},{"type":"paragraph","content":[{"text":"Two Dominicans, one genre","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Reggaetón is filed as Puerto Rican music, and its history is usually told that way. The men who produced its biggest era were Dominican, and that fact keeps getting left out of the telling.","type":"text"}]}]}'::jsonb, 'published', id, 2 FROM artists WHERE slug = 'tunes';
